def bst_from_preorder(preorder):
 at=0
 def build(limit):
  nonlocal at
  if at==len(preorder) or preorder[at]>limit:return None
  node=TreeNode(preorder[at]);at+=1;node.left=build(node.val);node.right=build(limit);return node
 return build(float('inf'))

